require 'openssl'
require 'json'
require 'digest'

module CryptoVault
  class EncryptedStorage
    CIPHER_ALGO = 'aes-256-gcm'

    def initialize(master_key)
      @master_key = Digest::SHA256.digest(master_key)
      @nonce_counter = 0
    end

    def encrypt(plaintext)
      cipher = OpenSSL::Cipher.new(CIPHER_ALGO)
      cipher.encrypt
      cipher.key = @master_key
      iv = cipher.random_iv
      cipher.auth_data = "vault_v2"
      ciphertext = cipher.update(plaintext) + cipher.final
      tag = cipher.auth_tag
      { iv: iv, ciphertext: ciphertext, tag: tag }
    end

    def decrypt(envelope)
      decipher = OpenSSL::Cipher.new(CIPHER_ALGO)
      decipher.decrypt
      decipher.key = @master_key
      decipher.iv = envelope[:iv]
      decipher.auth_tag = envelope[:tag]
      decipher.auth_data = "vault_v2"
      decipher.update(envelope[:ciphertext]) + decipher.final
    end
  end

  class ContractState
    attr_reader :balances, :locked

    def initialize(storage)
      @storage = storage
      @balances = {}
      @locked = {}
      @call_stack = []
      @execution_context = nil
    end

    def set_balance(address, amount)
      encrypted = @storage.encrypt(amount.to_s)
      @balances[address] = encrypted
    end

    def get_balance(address)
      return 0 unless @balances.key?(address)
      @storage.decrypt(@balances[address]).to_i
    end

    def acquire_lock(address)
      @locked[address] = true
    end

    def release_lock(address)
      @locked[address] = false
    end

    def is_locked?(address)
      @locked.fetch(address, false)
    end

    def push_context(ctx)
      @call_stack.push(ctx)
      @execution_context = ctx
    end

    def pop_context
      @call_stack.pop
      @execution_context = @call_stack.last
    end

    def current_depth
      @call_stack.length
    end
  end

  class VaultContract
    MAX_CALL_DEPTH = 8

    def initialize(master_key)
      @storage = EncryptedStorage.new(master_key)
      @state = ContractState.new(@storage)
      @callbacks = {}
      @reentrancy_guard = {}
    end

    def deposit(sender, amount)
      raise "Invalid amount" unless amount.positive?
      current = @state.get_balance(sender)
      @state.set_balance(sender, current + amount)
      { status: :ok, balance: current + amount }
    end

    def register_callback(address, &block)
      @callbacks[address] = block
    end

    def withdraw(sender, amount)
      raise "Invalid amount" unless amount.positive?

      # Check reentrancy guard using method-level mutex
      guard_key = compute_guard_key(sender, :withdraw)
      check_and_set_guard(guard_key)

      begin
        current = @state.get_balance(sender)
        raise "Insufficient balance" if current < amount

        # Notify callback before state update (simulates external call)
        # The guard should prevent reentrant calls
        notify_withdrawal(sender, amount, current)

        # Update state after callback
        new_balance = @state.get_balance(sender) - amount
        @state.set_balance(sender, new_balance)

        { status: :ok, withdrawn: amount, remaining: new_balance }
      ensure
        clear_guard(guard_key)
      end
    end

    def flash_loan(sender, amount, &arbitrage_block)
      raise "Invalid amount" unless amount.positive?

      pool_balance = @state.get_balance(:pool)
      raise "Pool insufficient" if pool_balance < amount

      # Transfer to borrower
      @state.set_balance(:pool, pool_balance - amount)
      borrower_bal = @state.get_balance(sender)
      @state.set_balance(sender, borrower_bal + amount)

      # Execute arbitrage (external call)
      @state.push_context({ caller: sender, type: :flash_loan })
      arbitrage_block.call(self, sender, amount) if arbitrage_block
      @state.pop_context

      # Verify repayment
      final_pool = @state.get_balance(:pool)
      raise "Flash loan not repaid" if final_pool < pool_balance

      { status: :ok, profit: final_pool - pool_balance }
    end

    private

    def compute_guard_key(sender, method)
      # Guard is scoped to sender + method combination
      "#{sender}:#{method}"
    end

    def check_and_set_guard(key)
      if @reentrancy_guard[key]
        raise "Reentrancy detected for #{key}"
      end
      @reentrancy_guard[key] = true
    end

    def clear_guard(key)
      @reentrancy_guard[key] = false
    end

    def notify_withdrawal(sender, amount, pre_balance)
      return unless @callbacks.key?(sender)

      @state.push_context({ caller: sender, type: :withdrawal_notify })

      if @state.current_depth <= MAX_CALL_DEPTH
        @callbacks[sender].call(self, amount, pre_balance)
      end

      @state.pop_context
    end
  end
